-- frikfrik protected build
return (function()
local LU="https://raw.githubusercontent.com/TitlePlugins/frikfrik/main/license.txt"
local LV="FRIKFRIK_OK_2026"
local ok_lic, lic = pcall(function() return game:HttpGet(LU .. "?t=" .. tostring(math.random(1,1e9)), true) end)
if ok_lic and type(lic) == "string" and #lic > 0 then
    local trimmed = lic:gsub("%s+$", "")
    if trimmed ~= LV then
        error("[frikfrik] license mismatch", 0)
    end
end
local D=""
local K1="L4mDucKfr1kfr1k2026PrTctK3y!_x9"
local K2="x@7Wq#Z9p%K!eR2t&Mb*Vn^Fj$Gh~D5"
local function b64dec(s)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i = 1, #alphabet do lookup[alphabet:sub(i,i)] = i - 1 end
    local out = {}
    local buf = 0
    local bits = 0
    for i = 1, #s do
        local ch = s:sub(i, i)
        if ch == "=" then break end
        local v = lookup[ch]
        if v then
            buf = buf * 64 + v
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local divisor = 2 ^ bits
                local byte = math.floor(buf / divisor)
                buf = buf - byte * divisor
                out[#out + 1] = string.char(byte)
            end
        end
    end
    return table.concat(out)
end
local dec = b64dec(D)
local bxor = bit32.bxor
local sb = string.byte
local sc = string.char
local k1len = #K1
local k2len = #K2
local out = {}
for i = 1, #dec do
    local b1 = bxor(sb(dec, i), sb(K1, ((i - 1) % k1len) + 1))
    out[i] = sc(bxor(b1, sb(K2, ((i - 1) % k2len) + 1)))
end
local code = table.concat(out)
local fn, err = loadstring(code, "main")
if not fn then error("[frikfrik] loadstring fail: " .. tostring(err), 0) end
return fn()
end)()
